use serde_json::{Value,json};use std::{fs,io,path::PathBuf};use crate::{state,atomic};
pub fn refresh()->io::Result<PathBuf>{let h=crate::home();let mut v:Value=serde_json::from_str(&fs::read_to_string(h.join("models_cache.json"))?)?;let a=v.get_mut("models").and_then(Value::as_array_mut).ok_or_else(||io::Error::other("models missing"))?;let mut seen=[false;3];for x in a{match x.get("slug").and_then(Value::as_str){Some("gpt-5.6-sol")=>{seen[0]=true;let o=x.as_object_mut().unwrap();o.insert("context_window".into(),json!(1050000));o.insert("max_context_window".into(),json!(1050000));o.insert("auto_compact_token_limit".into(),json!(950000));},Some("terra")=>seen[1]=true,Some("luna")=>seen[2]=true,_=>{}}}if seen.iter().any(|x|!*x){return Err(io::Error::other("Sol, Terra, or Luna missing"))}let p=state::dir().join("models-overlay.json");atomic(&p,&serde_json::to_vec(&v).unwrap())?;Ok(p)}
